/**
* Serializes an instance to a JSON object.
*
* ## Notes
*
* -   This method is implicitly invoked by `JSON.stringify`.
*
* @name toJSON
* @memberof Title.prototype
* @type {Function}
* @returns {Object} JSON object
*
* @example
* var title = new Title({
*     'text': 'Beep boop'
* });
*
* var v = title.toJSON();
* // returns {...}
*/
setNonEnumerableReadOnly( Title.prototype, 'toJSON', function toJSON() {
	return instance2json( this, properties );
});


